SZGame3D.runProject(function __szProjectRun() {
  const __szProjectRunContext = window.__SZProjectLifecycle.begin(() => SZGame3D.restart());
  // Ao iniciar
  const cena = SZGame3D.createFullscreenScene("#020617");
  SZGame3D.setSky(cena, "#020617", "#312e81");
  SZGame3D.setFog(cena, "#0b1030", 30, 75);
  SZGame3D.setCameraPosition(cena, 0, 8, 12);
  const cenario = SZGame3D.createModelFile(cena, "cenario-orbita", 180);
  const alvoCamera = SZGame3D.createModel(cena);
  SZGame3D.setPosition(alvoCamera, 0, 1, -12);
  SZGame3D.cameraLookAt(cena, alvoCamera);
  const nave = SZGame3D.createModelFile(cena, "nave-falcao-azul", 3);
  SZGame3D.setPosition(nave, 0, 1, 0);
  const moldeAsteroide = SZGame3D.createModelFile(cena, "asteroide-rocha-lunar", 1.8);
  SZGame3D.setVisible(moldeAsteroide, "hide");
  const moldeTiro = SZGame3D.createModelFile(cena, "laser-ciano", 0.9);
  SZGame3D.setVisible(moldeTiro, "hide");
  const tiros = SZGame3D.createGroup();
  const asteroides = SZGame3D.createGroup();
  let naveX = 0;
  let alvoAtivo = true;
  let velocidadeTiros = -22;
  let velocidadeAsteroides = 7;
  let pontos = 0;
  let estado = "inicio";
  SZGame3D.setLife(nave, 3);
  const moldePlasmaItem = SZGame3D.createModelFile(cena, "item-plasma-redondo", 1.6);
  SZGame3D.setVisible(moldePlasmaItem, "hide");
  const moldePlasma = SZGame3D.createModelFile(cena, "plasma-roxo", 0.8);
  SZGame3D.setVisible(moldePlasma, "hide");
  const itensPlasma = SZGame3D.createGroup();
  const tirosPlasma = SZGame3D.createGroup();
  let arma = "laser";
  let plasmaLiberado = false;
  SZGame3D.setScreenText("fim", "Vamos tentar outra vez?", "Sua nave pode abrir esta rota. Volte ao início para uma nova patrulha.", "Voltar ao início");
  SZGame3D.setScreenText("vitoria", "Rota liberada!", "Você abriu passagem por 20 asteroides. A patrulha pode continuar!", "Voltar ao início");
  SZGame3D.hudText("top-center", "PATRULHA ESPACIAL | Abra uma rota entre os asteroides");
  SZGame3D.hudText("top-right", "Acertos: 0 / 20");
  SZGame3D.hudText("top-left", "Arma: " + arma);
  SZGame3D.hudText("bottom-center", "ENTER: começar | SETAS: mover | ESPAÇO: atirar");
  // Quando acontecer
  SZGame3D.onKey("Enter", () => {
    if (estado === "inicio") {
      estado = "jogando";
      SZGame3D.hudText("top-center", "Abra a rota: acerte 20 asteroides e proteja sua nave");
      SZGame3D.hudText("bottom-center", "SETAS: mover | ESPAÇO: atirar");
    }
  });
  SZGame3D.onKey("Space", () => {
    if (estado === "jogando") {
      if (arma === "plasma") {
        SZGame3D.spawnCopy(tirosPlasma, moldePlasma, SZGame3D.getPos(nave, "x"), 1, -1.6);
        SZGame3D.playNote(330, 120);
      } else {
        SZGame3D.spawnCopy(tiros, moldeTiro, SZGame3D.getPos(nave, "x"), 1, -1.6);
        SZGame3D.playNote(880, 60);
      }
    }
  });
  SZGame3D.onTouchGroup(nave, asteroides, (asteroideQueBateu) => {
    if (estado === "jogando") {
      SZGame3D.removeFromGroup(asteroides, asteroideQueBateu);
      SZGame3D.hurt(nave, 1);
      SZGame3D.playEffect("hit");
    }
  });
  SZGame3D.onKey("KeyE", () => {
    if (estado === "jogando") {
      if (plasmaLiberado === true) {
        if (arma === "laser") {
          arma = "plasma";
        } else {
          arma = "laser";
        }
        SZGame3D.hudText("top-left", "Arma: " + arma);
      }
    }
  });
  SZGame3D.onTouchGroup(nave, itensPlasma, (itemPego) => {
    if (estado === "jogando") {
      SZGame3D.removeFromGroup(itensPlasma, itemPego);
      plasmaLiberado = true;
      SZGame3D.playEffect("coin");
    }
  });
  // Enquanto estiver rodando
  SZGame3D.animate(cena, () => {
    if (estado === "jogando") {
      if (SZGame3D.lifeOf(nave) <= 0) {
        estado = "derrota";
        SZGame3D.hudText("bottom-center", "");
        SZGame3D.endGame("perdeu");
      } else {
        if (pontos >= 20) {
          estado = "vitoria";
          SZGame3D.hudText("bottom-center", "");
          SZGame3D.playEffect("coin");
          SZGame3D.endGame("ganhou");
        }
      }
    }
    if (estado === "jogando") {
      if (SZGame3D.keyDown("ArrowLeft")) {
        naveX = naveX - 7 * SZGame3D.dt(cena);
      }
      if (SZGame3D.keyDown("ArrowRight")) {
        naveX = naveX + 7 * SZGame3D.dt(cena);
      }
      if (naveX < -5.2) {
        naveX = -5.2;
      }
      if (naveX > 5.2) {
        naveX = 5.2;
      }
      SZGame3D.setPosition(nave, naveX, 1, 0);
      SZGame3D.forEachInGroup(tiros, (tiro) => {
        SZGame3D.setVelocity(tiro, 0, 0, velocidadeTiros);
      });
      SZGame3D.updateGroupNoGravity(tiros);
      SZGame3D.forEachInGroup(asteroides, (asteroide) => {
        SZGame3D.setVelocity(asteroide, 0, 0, velocidadeAsteroides);
      });
      SZGame3D.updateGroupNoGravity(asteroides);
      SZGame3D.forEachInGroup(itensPlasma, (item) => {
        SZGame3D.setVelocity(item, 0, 0, velocidadeAsteroides);
      });
      SZGame3D.updateGroupNoGravity(itensPlasma);
      SZGame3D.forEachInGroup(tirosPlasma, (plasma) => {
        SZGame3D.setVelocity(plasma, 0, 0, -11);
      });
      SZGame3D.updateGroupNoGravity(tirosPlasma);
      SZGame3D.forEachInGroup(asteroides, (asteroide) => {
        alvoAtivo = true;
        SZGame3D.forEachInGroup(tirosPlasma, (plasma) => {
          if (alvoAtivo) {
            if (SZGame3D.collides(plasma, asteroide)) {
              SZGame3D.removeFromGroup(asteroides, asteroide);
              SZGame3D.removeFromGroup(tirosPlasma, plasma);
              pontos = pontos + 1;
              alvoAtivo = false;
              SZGame3D.playEffect("coin");
              SZGame3D.hudText("top-right", "Acertos: " + pontos + " / 20");
            }
          }
        });
      });
      SZGame3D.forEachInGroup(asteroides, (asteroide) => {
        alvoAtivo = true;
        SZGame3D.forEachInGroup(tiros, (tiro) => {
          if (alvoAtivo) {
            if (SZGame3D.collides(tiro, asteroide)) {
              SZGame3D.removeFromGroup(asteroides, asteroide);
              SZGame3D.removeFromGroup(tiros, tiro);
              pontos = pontos + 1;
              alvoAtivo = false;
              SZGame3D.playEffect("coin");
              SZGame3D.hudText("top-right", "Acertos: " + pontos + " / 20");
            }
          }
        });
      });
      SZGame3D.pruneArea(tiros, "z", -36, 3);
      SZGame3D.pruneArea(asteroides, "z", -36, 6);
      SZGame3D.pruneArea(itensPlasma, "z", -36, 6);
      SZGame3D.pruneArea(tirosPlasma, "z", -36, 3);
    }
  });
  SZGame3D.everySecondsLoop(1.5, () => {
    if (estado === "jogando") {
      SZGame3D.spawnCopy(asteroides, moldeAsteroide, Math.random() * 10.4 - 5.2, 1, -28);
    }
  });
  SZGame3D.everySecondsLoop(4, () => {
    if (estado === "jogando") {
      SZGame3D.spawnCopy(itensPlasma, moldePlasmaItem, -4, 1, -20);
    }
  });
});

